// 解析微信文章HTML内容
const cheerio = require('cheerio');

// 获取HTML内容
const html = $input.first().json.data;
const $ = cheerio.load(html);

// 提取标题
let title = '';
title = $('#activity-name').text().trim() || 
         $('h1').first().text().trim() || 
         $('title').text().trim();

// 提取正文内容
let content = '';
const contentSelectors = [
    '#js_content',
    '.rich_media_content', 
    '.article-content',
    '.content'
];

for (const selector of contentSelectors) {
    const element = $(selector);
    if (element.length > 0) {
        content = element.text().trim();
        break;
    }
}

// 清理内容
content = content
    .replace(/\s+/g, ' ')
    .replace(/微信号.*?功能介绍/g, '')
    .replace(/长按二维码识别.*?$/, '')
    .trim();

// 获取原始链接
const originalUrl = $input.first().json.article_url || '';

// 返回提取的数据
return {
    title: title,
    content: content,
    url: originalUrl,
    extracted_at: new Date().toISOString()
};

// 处理DeepSeek API响应
const aiResponse = $input.first().json;
let summary = '';

try {
    if (aiResponse.choices && aiResponse.choices.length > 0) {
        summary = aiResponse.choices[0].message.content.trim();
    } else {
        summary = '总结生成失败';
    }
} catch (error) {
    summary = '总结解析错误: ' + error.message;
}

// 合并所有数据
const previousData = $input.first().json;
return {
    ...previousData,
    summary: summary,
    processed_at: new Date().toISOString()
};
